<script setup>
import {computed,ref,watch,onMounted,onBeforeUnmount,defineAsyncComponent} from 'vue'
import {useRoute,useRouter} from 'vue-router'
import {Play,Pause,RotateCcw,StepForward,Save,Download,FolderOpen,Trash2,Check,ArrowRight,Calculator} from 'lucide-vue-next'
import {MODES,PARAMETERS} from '../../../machines/simulation/lunar-charge-control/parameters.js'
import {useExperiment,experimentSessions,DEFAULTS,SCENARIOS,normalize,MODEL_VERSION,listRuns,loadRun,saveRun,exportCSV,download} from './controller'
import {rpc} from '../transport'
const MoonScene=defineAsyncComponent(()=>import('./MoonScene.vue'))
import BenchDiagram from './BenchDiagram.vue'
import Chart from './Chart.vue'
const route=useRoute(),router=useRouter(),mode=computed(()=>route.params.mode)
const info=computed(()=>MODES.find(m=>m.id===mode.value))
const parameters=ref({...DEFAULTS}),appliedParameters=ref({...DEFAULTS}),applied=ref(''),scenario=ref(0),tab=ref('measurement'),message=ref(''),io=ref(false),saved=ref([]),comparison=ref(null),name=ref(''),upload=ref(null)
const {snapshot,samples,running,busy,error,speed,result,reset,step,toggle}=useExperiment()
const dirty=computed(()=>JSON.stringify(parameters.value)!==applied.value)
const groups=computed(()=>{const byGroup={};for(const p of PARAMETERS.filter(p=>p.modes.includes(mode.value))){if(p.key==='initialCharge'&&parameters.value.initialMode!=='charge'||p.key==='initialVoltage'&&parameters.value.initialMode!=='voltage'||p.key==='inputCharge'&&parameters.value.inputMode!=='charge'||p.key==='inputVoltage'&&parameters.value.inputMode!=='voltage')continue;(byGroup[p.group]||=[]).push(p)}return byGroup})
const series={voltage:[{key:'voltage',label:'Suit',unit:'kV',scale:.001,color:'#157c80'},{key:'environmentVoltage',label:'Environment',unit:'kV',scale:.001,color:'#b87930'}],current:[{key:'plasmaCurrent',label:'Plasma',unit:'µA',scale:1e6,color:'#2670ad'},{key:'triboCurrent',label:'Tribo',unit:'µA',scale:1e6,color:'#a97724'},{key:'emitterCurrent',label:'Emitter',unit:'µA',scale:1e6,color:'#157c80'},{key:'landerCurrent',label:'Lander',unit:'µA',scale:1e6,color:'#89549f'}],energy:[{key:'fieldEnergy',label:'Field',unit:'J',scale:1,color:'#2670ad'},{key:'storage',label:'Storage',unit:'J',scale:1,color:'#157c80'},{key:'harvested',label:'Harvested',unit:'J',scale:1,color:'#b87930'}]}
const violations=computed(()=>{const s=snapshot.value;if(!s)return [];const flags=[];if(s.peakCurrent>.001+1e-12)flags.push('1 mA current limit exceeded');else if(s.peakCurrent>.0002+1e-12)flags.push('0.2 mA design target exceeded');if(appliedParameters.value.systemMass>=20)flags.push('Mass requirement of less than 20 kg not met');if(['discharge','moon','system'].includes(mode.value)&&s.finished&&(s.dischargeAt===null||s.dischargeAt>30))flags.push('Discharge target not reached within 30 s');if(s.emitterFailed)flags.push('Emitter failure');if(Math.abs(s.energyResidual)>1e-7)flags.push('Energy balance violated');return flags})
const explanation=computed(()=>({plasma:'Simplified current balance: thermal suppression of repelled electron and ion currents, with saturated collection of attracted particles. Photoemission is absent in shadow. No spatial plasma sheath or PIC simulation.',tribo:'Discrete material-dependent charge transfers after contact and separation. Material, force and timing factors are adjustable model assumptions, not measurements. Transfers are bounded by available step work. Internal generator work and external net charge are separate.',harvester:'Isolated converters draw energy only from an internal capacitor or mechanical step work. They do not remove external net charge. Only the collector concept has an explicit external return path. Ambient plasma collection is active in the separate plasma bench and EVA.',emitter:'Idealized charge-balance model. Only escaping electrons contribute to external net current. Storage supplies operating power; released field energy is assigned separately to particles. Space charge, fields and electron recapture are not spatially resolved.',discharge:'Analytic RC model with optional current limiting and contact interruption. Cable and contact capacitances are connected to the suit from the start. This does not demonstrate protection against pre-contact arcing.',moon:'Shared EVA model: 0–38% illuminated route, 38–65% permanent shadow, 65–75% return, and lander contact from 75%. Terrain illustrates these phases spatially; the field shell and particles are symbolic.',system:'All submodels share the same time and charge balance. Environmental conditions change by phase; current-limited contact takes over at the lander. Electrical limit checks do not establish contact safety.'}[mode.value]))
const f=(n,d=3)=>Number(n||0).toLocaleString('en-GB',{maximumFractionDigits:d,minimumFractionDigits:d})
async function apply(){try{const p=normalize(parameters.value);await reset(mode.value,p);if(error.value)throw Error(error.value);appliedParameters.value={...p};applied.value=JSON.stringify(parameters.value);message.value=''}catch(e){message.value=e.message}}
async function choose(){running.value=false;comparison.value=null;parameters.value={...DEFAULTS,...SCENARIOS[mode.value][scenario.value].values};await apply()}
async function start(){if(dirty.value)await apply();if(!dirty.value&&!error.value)toggle()}
async function next(){if(dirty.value)await apply();if(!dirty.value&&!error.value)await step(.1)}
async function calculate(){if(dirty.value)await apply();if(!dirty.value&&!error.value){running.value=false;await step(parameters.value.duration)}}
async function refresh(){try{saved.value=await listRuns()}catch(e){message.value=e.message}}
async function store(){if(!result.value)return;io.value=true;try{await saveRun(result.value,name.value||`${info.value.title} · ${new Date().toLocaleString('en-GB')}`);message.value='Experiment saved.';await refresh()}catch(e){message.value=e.message}finally{io.value=false}}
async function restore(row){io.value=true;try{const r=await loadRun(row.id);if(r.modelVersion!==MODEL_VERSION)throw Error('The saved model version is not supported.');parameters.value=normalize(r.parameters);await apply();comparison.value=r;tab.value='measurement'}catch(e){message.value=e.message}finally{io.value=false}}
async function compare(row){io.value=true;try{comparison.value=await loadRun(row.id);tab.value='measurement'}catch(e){message.value=e.message}finally{io.value=false}}
async function remove(row){io.value=true;try{await rpc('lunar.runs.delete',{tid:row.id});if(comparison.value?.id===row.id)comparison.value=null;await refresh()}catch(e){message.value=e.message}finally{io.value=false}}
function exportParameters(){download(`lcc-${mode.value}-parameter.json`,JSON.stringify({modelVersion:MODEL_VERSION,mode:mode.value,parameters:parameters.value},null,2))}
async function importParameters(event){const file=event.target.files?.[0];if(!file)return;try{if(file.size>64000)throw Error('Parameter file is too large.');const value=JSON.parse(await file.text());if(value.modelVersion!==MODEL_VERSION||value.mode!==mode.value)throw Error('Test bench or model version does not match.');parameters.value=normalize(value.parameters);await apply()}catch(e){message.value=e.message}finally{event.target.value=''}}
function remember(id){if(id&&snapshot.value)experimentSessions.set(id,{parameters:{...appliedParameters.value},time:snapshot.value.time,scenario:scenario.value})}
watch(mode,async(nextMode,previousMode)=>{remember(previousMode);tab.value='measurement';comparison.value=null;const cached=experimentSessions.get(nextMode);if(cached){scenario.value=cached.scenario;parameters.value={...cached.parameters};await apply();if(cached.time>0)await step(cached.time)}else{scenario.value=0;await choose()}},{immediate:true})
onBeforeUnmount(()=>remember(mode.value))
onMounted(refresh)
</script>
<template><div class="lcc-workbench"><div class="lcc-heading"><div><div class="eyebrow">LCC / DEVELOPMENT ENVIRONMENT</div><h1>{{info?.title}}</h1></div><div class="lcc-run-controls"><button class="button primary" :disabled="busy||snapshot?.finished&&!dirty" @click="start"><Pause v-if="running" :size="16"/><Play v-else :size="16"/>{{running?'Pause':'Start'}}</button><button class="icon-button" :disabled="running||busy" title="Advance 0.1 seconds" aria-label="Advance 0.1 seconds" @click="next"><StepForward :size="19"/></button><button class="icon-button" :disabled="busy" title="Reset experiment" aria-label="Reset experiment" @click="apply"><RotateCcw :size="18"/></button><button class="icon-button" :disabled="busy" title="Calculate to completion" aria-label="Calculate to completion" @click="calculate"><Calculator :size="19"/></button><select v-model.number="speed" aria-label="Playback speed"><option v-for="n in [1,5,20,100]" :value="n">{{n}}×</option></select><span class="experiment-clock">{{f(snapshot?.time,2)}} / {{f(appliedParameters.duration,1)}} s</span></div></div>
<div v-if="message||error" class="lcc-notice" role="status">{{error||message}}<button @click="message='';error=''" aria-label="Dismiss message">×</button></div>
<div class="lcc-metrics"><div><span>Suit potential</span><strong>{{f((snapshot?.voltage||0)/1000,2)}}<small>kV</small></strong></div><div><span>Net charge</span><strong>{{f((snapshot?.charge||0)*1e6,3)}}<small>µC</small></strong></div><div><span>Storage</span><strong>{{f(snapshot?.storage,4)}}<small>J</small></strong></div><div><span>Harvested</span><strong>{{f((snapshot?.harvested||0)*1000,3)}}<small>mJ</small></strong></div><div><span>Electrical checks</span><strong class="metric-status" :class="{warning:violations.length}">{{violations.length?'Limit / fault':snapshot?.finished?'Calculated':running?'Calculation active':snapshot?.time?'Paused':'Ready'}}</strong><small v-if="running">Playback active</small></div></div>
<div class="lcc-workspace"><aside class="lcc-parameters"><header><h2>Experiment parameters</h2><button class="icon-button" title="Export parameters" aria-label="Export parameters" @click="exportParameters"><Download :size="17"/></button><button class="icon-button" title="Import parameters" aria-label="Import parameters" @click="upload.click()"><FolderOpen :size="17"/></button><input ref="upload" hidden type="file" accept="application/json,.json" @change="importParameters"/></header><div class="parameter-scenario"><label for="lcc-scenario">Experiment scenario</label><select id="lcc-scenario" v-model.number="scenario" :disabled="running" @change="choose"><option v-for="(s,i) in SCENARIOS[mode]" :value="i">{{s.name}}</option></select></div><div class="parameter-scroll"><details v-for="(fields,group) in groups" :key="group" :open="['Experiment','Suit'].includes(group)"><summary>{{group}}<span>{{fields.length}}</span></summary><div v-for="p in fields" :key="p.key" class="parameter-field"><label :for="'param-'+p.key">{{p.label}}<small v-if="p.unit">{{p.unit}}</small></label><select v-if="p.options" :id="'param-'+p.key" v-model="parameters[p.key]" :disabled="running"><option v-for="(label,value) in p.options" :value="value">{{label}}</option></select><input v-else-if="typeof p.value==='boolean'" :id="'param-'+p.key" v-model="parameters[p.key]" type="checkbox" :disabled="running"/><input v-else :id="'param-'+p.key" v-model.number="parameters[p.key]" type="number" :min="p.min" :max="p.max" :step="p.step" :disabled="running"/></div></details></div><button v-if="dirty" class="button secondary apply-parameters" :disabled="running||busy" @click="apply"><Check :size="16"/>Apply parameters</button><div class="parameter-version">Model {{MODEL_VERSION}} · SI engine</div></aside>
<section class="lcc-results"><nav class="lcc-tabs" aria-label="Experiment views"><button :class="{active:tab==='measurement'}" @click="tab='measurement'">Live measurements</button><button :class="{active:tab==='runs'}" @click="tab='runs';refresh()">Experiment runs</button><button :class="{active:tab==='model'}" @click="tab='model'">Model & balance</button><div class="lcc-result-actions"><input v-model="name" placeholder="Experiment name" aria-label="Experiment name"/><button class="icon-button" :disabled="!result||io||running" title="Save experiment" aria-label="Save experiment" @click="store"><Save :size="18"/></button><button class="icon-button" :disabled="!result" title="Export measurements as CSV" aria-label="Export measurements as CSV" @click="exportCSV(result)"><Download :size="18"/></button></div></nav>
<div v-if="tab==='measurement'" class="lcc-measurement"><MoonScene v-if="['moon','system'].includes(mode)" :state="snapshot" :initial-component="String(route.query.component||'')" @presentation-start="running=false" @bench="router.push({path:'/lcc/'+$event.mode,query:{from:mode,component:$event.component}})"/><BenchDiagram v-else :mode="mode" :state="snapshot" :parameters="appliedParameters"/><div v-if="violations.length" class="limit-strip" role="status"><span v-for="v in violations" :key="v">{{v}}</span></div><div v-else class="limit-strip neutral"><span>{{snapshot?.phase}}</span><span v-if="['discharge','system','moon'].includes(mode)">Contact model: pre-contact arcing not calculated</span><span v-else>Calculated model values</span></div><div class="lcc-charts"><Chart title="Potential" :samples="samples" :fields="series.voltage" :comparison="comparison"/><Chart title="Charge currents" :samples="samples" :fields="series.current" :comparison="comparison"/><Chart title="Electrical energy" :samples="samples" :fields="series.energy" :comparison="comparison"/></div><button v-if="comparison" class="clear-comparison" @click="comparison=null">Hide comparison: {{comparison.title}} ×</button></div>
<div v-else-if="tab==='runs'" class="lcc-records"><header><h2>Saved experiments</h2><small>Immutable measurement series with parameters and model version</small></header><table><thead><tr><th>Experiment name</th><th>Timestamp</th><th>Model</th><th></th></tr></thead><tbody><tr v-for="row in saved.filter(r=>r.kind===mode)" :key="row.id"><td>{{row.title}}</td><td>{{row.created}}</td><td>{{row.state}}</td><td><button class="icon-button" :disabled="io" title="Compare with current experiment" @click="compare(row)"><ArrowRight :size="17"/></button><button class="icon-button" :disabled="io" title="Restore parameters" @click="restore(row)"><FolderOpen :size="17"/></button><button class="icon-button danger" :disabled="io" title="Delete experiment" @click="remove(row)"><Trash2 :size="17"/></button></td></tr></tbody></table><p v-if="!saved.some(r=>r.kind===mode)" class="lcc-empty">No experiments saved for this test bench yet.</p></div>
<div v-else class="lcc-model"><h2>Physical model</h2><p>{{explanation}}</p><div class="model-equations"><strong>Q = C · V</strong><strong>ΔQ = Σ I · Δt</strong><strong>E = ½ C · V²</strong><strong>ΔE = W<sub>external</sub> − E<sub>released</sub></strong></div><p>Positive currents increase positive suit charge. Electron collection is negative; electron emission is positive. Potentials share a fixed common reference. The constant-capacitance model does not solve spatial fields.</p><div class="balance-grid"><div><span>Charge balance residual</span><strong>{{(snapshot?.chargeResidual||0).toExponential(3)}} C</strong></div><div><span>Energy balance residual</span><strong>{{(snapshot?.energyResidual||0).toExponential(3)}} J</strong></div><div><span>Plasma power flow</span><strong>{{f((snapshot?.plasmaPower||0)*1000,6)}} mW</strong></div><div><span>Harvester output power</span><strong>{{f((snapshot?.harvestPower||0)*1000,6)}} mW</strong></div><div><span>Emitter target reached after</span><strong>{{snapshot?.neutralizedAt===null?'Not reached':f(snapshot?.neutralizedAt,3)+' s'}}</strong></div><div><span>External work (signed)</span><strong>{{f(snapshot?.externalWork,6)}} J</strong></div><div><span>Stored field energy</span><strong>{{f(snapshot?.fieldEnergy,6)}} J</strong></div><div><span>Internal capacitor field</span><strong>{{f(snapshot?.internalEnergy,6)}} J</strong></div><div><span>Conversion and leakage losses</span><strong>{{f(snapshot?.loss,6)}} J</strong></div><div><span>Electrical consumption</span><strong>{{f(snapshot?.consumed,6)}} J</strong></div><div><span>Field energy carried by emitted particles</span><strong>{{f(snapshot?.particleEnergy,6)}} J</strong></div><div><span>Emitted electron charge (magnitude)</span><strong>{{f((snapshot?.emittedCharge||0)*1e6,6)}} µC</strong></div><div><span>Time to discharge target</span><strong>{{snapshot?.dischargeAt===null?'Not reached':f(snapshot?.dischargeAt,3)+' s'}}</strong></div><div><span>Storage voltage</span><strong>{{f(snapshot?.storageVoltage,3)}} V</strong></div><div><span>Regulated output</span><strong>{{f(snapshot?.outputVoltage,3)}} V</strong></div><div><span>Output current (interval average)</span><strong>{{f((snapshot?.outputCurrent||0)*1000,3)}} mA</strong></div><div><span>Peak contact current</span><strong>{{f((snapshot?.peakCurrent||0)*1000,4)}} mA</strong></div></div><h3>Sources and limitations</h3><p>Discharge limits are taken from the <a href="https://work.crowdplat.com/challenge/lunar-grounding-challenge" target="_blank" rel="noreferrer">NASA Lunar Grounding Challenge</a>: 200 pF, −100 kV, approximately +100 V at the lander, a maximum of 1 mA (target ≤ 0.2 mA), 30 s and less than 20 kg. Material properties, plasma fluxes, efficiencies and sole factors are adjustable model assumptions. Charge and energy balances are calculated by the simulation engine; physical contact safety has not been demonstrated.</p></div>
</section></div></div></template>
